// Generate random wait between 0 and 3 hours (10800 seconds)
// This means posts go out anytime between 8am and 11am randomly
const min = 0;
const max = 10800;
const waitSeconds = Math.floor(Math.random() * (max - min + 1)) + min;
const waitMinutes = Math.round(waitSeconds / 60);

console.log(`Will wait ${waitMinutes} minutes before posting`);

return [{
  json: {
    waitSeconds,
    waitMinutes,
    scheduledFor: new Date(Date.now() + waitSeconds * 1000).toISOString()
  }
}];

// Get current day name and date info
const now = new Date();
const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const dayName = days[now.getDay()];
const dateStr = now.toISOString().split('T')[0];
const timeStr = now.toTimeString().split(' ')[0];

return [{
  json: {
    dayName,
    dateStr,
    timeStr,
    timestamp: now.toISOString(),
    year: now.getFullYear()
  }
}];

// Find today's topic from the rotation sheet
const dayName = $('Get Current Day').item.json.dayName;
const rows = $input.all();

const todayRow = rows.find(row => 
  row.json['Day'] === dayName && 
  String(row.json['Active']).trim().toUpperCase() === 'YES'
);

if (!todayRow) {
  throw new Error(`No active topic found for ${dayName}. Check the Topic Rotation sheet.`);
}

console.log(`Today is ${dayName} — Topic: ${todayRow.json['Topic Title']}`);

return [{
  json: {
    dayName,
    category: todayRow.json['Category'],
    topicTitle: todayRow.json['Topic Title'],
    topicDescription: todayRow.json['Description / Angle'],
    hashtags: todayRow.json['Hashtags'],
    dateStr: $('Get Current Day').item.json.dateStr
  }
}];

// Select the best unused idea for today's category
// Falls back to the topic description if no matching idea found

const topicData = $('Find Todays Topic').item.json;
const category = topicData.category;
const rows = $input.all();

// Filter: same category AND unused
const matchingIdeas = rows.filter(row => {
  const rowCategory = String(row.json['Category'] || '').trim();
  const rowStatus = String(row.json['Status'] || '').trim();
  return rowCategory === category && rowStatus === 'Unused';
});

let selectedIdea = null;
let ideaRowNumber = null;
let usingIdea = false;

if (matchingIdeas.length > 0) {
  // Prefer High priority, else pick any
  const highPriority = matchingIdeas.filter(r => 
    String(r.json['Priority']).trim() === 'High'
  );
  const pool = highPriority.length > 0 ? highPriority : matchingIdeas;

  // Random selection from pool for variety
  selectedIdea = pool[Math.floor(Math.random() * pool.length)];

  // Find row number in original array (+2 for header row offset)
  ideaRowNumber = rows.indexOf(selectedIdea) + 2;
  usingIdea = true;

  console.log(`Found idea: "${selectedIdea.json['Idea Title']}" (row ${ideaRowNumber})`);
} else {
  console.log(`No unused ideas for category "${category}" — using topic description as base`);
}

// Build Tavily research query
const researchQuery = usingIdea
  ? `${selectedIdea.json['Idea Title']} ${category} practical tips 2026`
  : `${topicData.topicTitle} ${category} latest trends statistics 2026`;

return [{
  json: {
    usingIdea,
    ideaTitle: usingIdea ? selectedIdea.json['Idea Title'] : topicData.topicTitle,
    ideaAngle: usingIdea ? selectedIdea.json['Full Idea / Angle'] : topicData.topicDescription,
    ideaRowNumber,
    category,
    hashtags: topicData.hashtags,
    researchQuery,
    dayName: topicData.dayName,
    dateStr: topicData.dateStr,
    topicTitle: topicData.topicTitle
  }
}];

// Build the Claude prompt — this is the most important node
// The quality of this prompt determines if the post sounds human or AI

const ideaData = $('Select Best Idea').item.json;
const researchData = $('Tavily Research').item.json;

// Extract and clean research results
let researchContext = '';
let researchAnswer = '';

try {
  if (researchData && researchData.results && researchData.results.length > 0) {
    researchAnswer = researchData.answer || '';
    researchContext = researchData.results
      .slice(0, 4)
      .map(r => `- ${r.title}: ${String(r.content || r.snippet || '').substring(0, 250)}`)
      .join('\n');
  }
} catch(e) {
  console.log('Research parsing failed, continuing without it');
  researchContext = 'Use your own expertise for this post.';
}

// The system prompt that defines Abdullah's voice
const systemPrompt = `You are Abdullah Tariq — a 20-something AI Automation Engineer from Pakistan working at Trilles AI. You build real production systems: voice AI agents (Vapi, Retell AI), n8n automations, LangChain pipelines, and AI chatbots for businesses worldwide.

You are writing a LinkedIn post RIGHT NOW from your own experience. You are NOT writing marketing copy. You are NOT an AI assistant. You are a real practitioner sharing what you actually know and do.

YOUR WRITING VOICE:
- Conversational, direct, slightly informal but professional
- Short sentences. Punchy. Like you typed this on your phone
- First person always — "I", "my clients", "we built", "I ran into"
- You name specific tools because you actually use them (n8n, Vapi, Retell AI, LangChain, Claude, Supabase, GHL)
- You share real frustrations and wins — not just wins
- You write like an engineer who knows what they're talking about, not a marketer
- Pakistani background, global client base — this is authentic context

HARD RULES — NEVER DO THESE:
- NEVER start with: "I'm excited", "Thrilled", "In today's world", "Are you tired of", "Let me share"
- NEVER use: game-changer, revolutionary, leverage, delve, unlock, seamless, cutting-edge, transformative, empower, reimagine
- NEVER write bullet point lists — use paragraph breaks instead
- NEVER sound like ChatGPT wrote it
- NEVER add hashtags in the middle of the post — only at the very end
- NEVER use em-dashes (—) more than once
- NEVER write more than 350 words
- NEVER start consecutive sentences with "I"

POST STRUCTURE (flexible, not rigid):
[Hook line — 1-2 sentences. A specific observation, bold claim, or real scenario. No questions.]

[blank line]

[Core content — 2-4 short paragraphs. Be specific. Use real numbers if research provides them. Share the actual insight, not a vague overview.]

[blank line]

[Closing — either a direct question to the audience OR a punchy one-liner takeaway. Keep it short.]

[blank line]

#hashtag1 #hashtag2 #hashtag3 #hashtag4`;

// The user prompt with the specific topic
const userPrompt = `Write a LinkedIn post about this:

Topic: ${ideaData.ideaTitle}
Angle to explore: ${ideaData.ideaAngle}
Category: ${ideaData.category}
Suggested hashtag themes (adapt them): ${ideaData.hashtags}

Fresh research/context to weave in naturally (pick 1-2 facts that are genuinely interesting — skip anything generic):
${researchAnswer ? `Summary: ${researchAnswer}\n` : ''}${researchContext}

Remember: Write as Abdullah — a real engineer sharing real experience. Not a blog post. Not a LinkedIn influencer post. Something authentic that a fellow engineer or business owner would actually read.`;

return [{
  json: {
    systemPrompt,
    userPrompt,
    ideaData,
    researchContext: researchContext.substring(0, 500)
  }
}];

// Parse Claude response and clean the post

const response = $input.item.json;

if (!response || !response.content || !response.content[0]) {
  throw new Error('Claude API returned empty response. Check your API key and credits.');
}

let postContent = response.content[0].text.trim();

// Remove common AI preamble patterns
postContent = postContent.replace(/^(here'?s? (the |a )?post:?\s*)/i, '');
postContent = postContent.replace(/^(linkedin post:?\s*)/i, '');
postContent = postContent.replace(/^["']/, '').replace(/["']$/, '');

// Ensure post isn't too long for LinkedIn (max 3000 chars, we want under 700)
if (postContent.length > 700) {
  console.log(`Post too long (${postContent.length} chars), trimming...`);
  // Cut at last paragraph before 700 chars
  const trimmed = postContent.substring(0, 700);
  const lastNewline = trimmed.lastIndexOf('\n');
  postContent = lastNewline > 400 ? trimmed.substring(0, lastNewline) : trimmed;
}

// Extract just the title (first line) for logging
const firstLine = postContent.split('\n')[0].trim();
const postTitle = firstLine.length > 80 ? firstLine.substring(0, 80) + '...' : firstLine;

// Get idea metadata
const ideaData = $('Select Best Idea').item.json;

console.log(`Post generated successfully: ${postTitle}`);
console.log(`Post length: ${postContent.length} characters`);

return [{
  json: {
    postContent,
    postTitle,
    postLength: postContent.length,
    category: ideaData.category,
    ideaTitle: ideaData.ideaTitle,
    ideaRowNumber: ideaData.ideaRowNumber,
    usingIdea: ideaData.usingIdea,
    hashtags: ideaData.hashtags,
    dateStr: ideaData.dateStr,
    dayName: ideaData.dayName
  }
}];

