// Combine post content with image URL
// Handles case where image generation failed

const postData = $('Parse Post Content').item.json;
let imageUrl = '';

try {
  const imageResponse = $('Generate Post Image').item.json;
  imageUrl = imageResponse.url || '';
  if (imageUrl) {
    console.log(`Image generated: ${imageUrl}`);
  }
} catch(e) {
  console.log('Image generation skipped or failed — posting text only');
}

return [{
  json: {
    ...postData,
    imageUrl,
    hasImage: !!imageUrl
  }
}];

// Check LinkedIn post result
let linkedInUrl = '';
let linkedInStatus = 'posted';

try {
  const liResult = $('Post to LinkedIn').item.json;
  // LinkedIn returns the post URN/ID
  linkedInUrl = liResult.id ? `https://www.linkedin.com/feed/update/${liResult.id}` : '';
} catch(e) {
  linkedInStatus = 'failed';
  console.log('LinkedIn post status check failed');
}

const postData = $('Combine Post and Image').item.json;

return [{
  json: {
    ...postData,
    linkedInUrl,
    linkedInStatus,
    emailStatus: 'sent'
  }
}];

// Update the used idea status in Content Ideas sheet
// Only runs if we actually used an idea (not fallback)

const data = $('Collect Results').item.json;

if (!data.usingIdea || !data.ideaRowNumber) {
  console.log('No idea was selected — skipping status update');
  return [{ json: { updated: false, reason: 'No idea used' } }];
}

console.log(`Will mark idea row ${data.ideaRowNumber} as Used`);

return [{
  json: {
    updated: true,
    ideaRowNumber: data.ideaRowNumber,
    ideaTitle: data.ideaTitle,
    dateStr: data.dateStr
  }
}];

const data = $('Collect Results').item.json;
console.log(`
=== WORKFLOW COMPLETE ===
Date: ${data.dateStr}
Category: ${data.category}
Post: ${data.postTitle}
LinkedIn: ${data.linkedInStatus}
Email: sent to abdtariq3274@gmail.com
Image: ${data.hasImage ? data.imageUrl : 'none'}
========================
`);

return [{ json: { status: 'success', ...data } }];
